/* Shared navigation and media actions, independent of which view contains a tile. */
(function(root){
 function breadcrumbs(hash,collection,type){const rows=[{label:'My space',href:'#home'}];if(hash==='#home'||!hash)return [...rows,{label:'Home',href:'#home'}];if(hash==='#search')return [...rows,{label:'Search',href:'#search'}];if(hash==='#profile')return [...rows,{label:'Profile',href:'#profile'}];rows.push({label:'Library',href:'#library'});if(hash==='#library/insights')rows.push({label:'Insights',href:hash});else if(collection)rows.push({label:collection,href:'#library',action:'collection'});else if(type&&type!=='All media')rows.push({label:type,href:'#library',action:'type'});return rows;}
 if(typeof module==='object')module.exports={breadcrumbs};if(typeof document==='undefined')return;
 function paint(){const header=document.querySelector('main>header>span'),collection=selectedCollection!=='all'?collections.find(c=>c.id===selectedCollection)?.name:collectionSpace?'Collections':'';const rows=breadcrumbs(location.hash,collection,type);header.innerHTML=`<nav class="page-directory" aria-label="Page directory">${rows.map((r,i)=>`${i?'<span aria-hidden="true">/</span>':''}${i===rows.length-1?`<span aria-current="page">${esc(r.label)}</span>`:`<a href="${r.href}" ${r.href==='#library'?'data-library-root="true"':''}>${esc(r.label)}</a>`}`).join('')}</nav>`;header.querySelector('[data-library-root]')?.addEventListener('click',()=>{selectedCollection='all';collectionSpace=false;type='All media';view='all';render();});}
 const previousRender=render;render=function(){previousRender();paint();};paint();
 function position(trigger,x,y){const menu=document.querySelector('#item-menu'),host=trigger.closest('dialog')||document.body,dialog=host.tagName==='DIALOG';host.append(menu);const zoom=Number.parseFloat(getComputedStyle(document.documentElement).zoom)||1,rect=dialog?host.getBoundingClientRect():null,scale=dialog?rect.width/host.offsetWidth||zoom:zoom;menu.style.position=dialog?'absolute':'fixed';menu.style.maxHeight=(dialog?host.clientHeight:window.innerHeight/zoom)-20+'px';menu.style.overflowY='auto';const point=root.FolioFeedback.coordinates(x,y,zoom,dialog?{left:rect.left,top:rect.top,scale,scrollLeft:host.scrollLeft,scrollTop:host.scrollTop,clientLeft:host.clientLeft,clientTop:host.clientTop}:null);menu.style.left=Math.max((dialog?host.scrollLeft:0)+8,Math.min(point.x,(dialog?host.scrollLeft+host.clientWidth:window.innerWidth/zoom)-menu.offsetWidth-8))+'px';menu.style.top=Math.max((dialog?host.scrollTop:0)+8,Math.min(point.y,(dialog?host.scrollTop+host.clientHeight:window.innerHeight/zoom)-menu.offsetHeight-8))+'px';menu.querySelector('button')?.focus({preventScroll:true});}
 const previousMenu=openItemMenu;openItemMenu=function(id,x,y,trigger){previousMenu(id,x,y,trigger);if(!trigger)return;position(trigger,x,y);const menu=document.querySelector('#item-menu'),click=menu.onclick;menu.onclick=e=>{if(['view','edit','progress'].includes(e.target.closest('[data-menu-action]')?.dataset.menuAction)){const dialog=trigger.closest('dialog');if(dialog){root.FolioDirectory?.before();dialog.close();}}click(e);};};
 function context(target){const saved=target.closest('[data-library-id],[data-shelf-title],[data-profile-title],[data-memory]');if(saved){const id=saved.dataset.libraryId||saved.dataset.shelfTitle||saved.dataset.profileTitle||saved.dataset.memory;return {entry:items.find(x=>x.id===id),trigger:saved};}const creator=target.closest('[data-creator-work]');if(creator){const media=root.FolioCreators.forElement(creator);if(media)return {media,entry:owned(fromMetadata(media)),trigger:creator};}const search=target.closest('.discover-card');if(search){const media=liveDisplayed.find(x=>x.id===search.querySelector('[data-preview]')?.dataset.preview);if(media)return {media,entry:owned(fromMetadata(media)),trigger:search.querySelector('button')};}const catalog=target.closest('[data-id],[data-recommend-id]');if(catalog){const id=catalog.dataset.id||catalog.dataset.recommendId,entry=items.find(x=>x.id===id),sample=catalogItems().find(x=>x.id===id);if(entry||sample)return {entry:entry||owned(sample),sample,trigger:catalog};}return null;}
 function open(event){const found=context(event.target);if(!found||(!found.entry&&!found.media&&!found.sample))return;event.preventDefault();event.stopImmediatePropagation();const {entry,media,sample,trigger}=found,rect=trigger.getBoundingClientRect(),x=event.type==='keydown'?rect.left+16:event.clientX,y=event.type==='keydown'?rect.bottom:event.clientY;if(entry){openItemMenu(entry.id,x,y,trigger);return;}closeItemMenu();const menu=document.querySelector('#item-menu');menu.innerHTML=`<div class="menu-title">${esc(media?.title||sample.title)}</div><button type="button" role="menuitem" data-media-action="view">View media</button><button type="button" role="menuitem" data-media-action="add">Add to library…</button>`;menu.hidden=false;menuTrigger=trigger;position(trigger,x,y);menu.onclick=e=>{const action=e.target.closest('[data-media-action]')?.dataset.mediaAction;if(!action)return;closeItemMenu();if(action==='view'){const dialog=trigger.closest('dialog');if(dialog){root.FolioDirectory?.before();dialog.close();}if(media)showLive(media);else openDetail(sample.id);}else if(media)importLive(media,trigger);else openCatalogAdd(sample.id);};}
 document.addEventListener('contextmenu',open,true);document.addEventListener('keydown',e=>{if(e.key==='ContextMenu'||(e.shiftKey&&e.key==='F10'))open(e);},true);
 document.addEventListener('close',e=>{if(document.querySelector('#item-menu')?.closest('dialog')===e.target)closeItemMenu();},true);
})(globalThis);
